long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret = -EINVAL;
    int i;

    if (nsops == 0)
        return 0;

    sops = kmalloc(nsops * sizeof(*sops), GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(*sops))) {
        kfree(sops);
        return -EFAULT;
    }

    for (i = 0; i < nsops; i++) {
        sops[i].sem_num = sops[i].sem_num;
        sops[i].sem_op = sops[i].sem_op;
        sops[i].sem_flg = sops[i].sem_flg;
    }

    if (timeout) {
        struct timespec ktimeout;
        if (copy_from_user(&ktimeout, timeout, sizeof(ktimeout))) {
            kfree(sops);
            return -EFAULT;
        }
        ret = do_semtimedop(semid, sops, nsops, &ktimeout);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

    kfree(sops);
    return ret;
}

long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret = -EINVAL;
    int i;

    if (nsops == 0)
        return 0;

    if (nsops > SEMOPM)
        goto out;

    sops = kmalloc(sizeof(*sops) * nsops, GFP_KERNEL);
    if (sops == NULL)
        goto out;

    if (copy_from_user(sops, tsops, sizeof(*sops) * nsops))
        goto out_free;

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to)))
            goto out_free;
    }

    ret = 0;

    for (i = 0; i < nsops; i++) {
        if (sops[i].sem_op != 0) {
            ret = -EAGAIN;
            break;
        }
    }

    if (ret == -EAGAIN) {
        if (timeout) {
            ret = do_semaphore_wait_with_timeout(sops, nsops);
        } else {
            ret = do_semaphore_wait(sops, nsops);
        }
    }

out_free:
    kfree(sops);
out:
    return ret;
}

