long do_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    long ret = 0;
    struct oabi_sembuf *sops = NULL;

    if (nsops == 0 || nsops > SEMOPM)
        return -EINVAL;

    sops = kmalloc(nsops * sizeof(struct oabi_sembuf), GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(struct oabi_sembuf))) {
        kfree(sops);
        return -EFAULT;
    }

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to))) {
            kfree(sops);
            return -EFAULT;
        }
        ret = do_semsys_call(semid, sops, nsops, &to);
    } else {
        ret = do_semsys_call(semid, sops, nsops, NULL);
    }

    kfree(sops);
    return ret;
}
